plain=[{'poem_id': 579, 'rationale': 'Keep the author’s grief and anger about Pahalgam in words, without invented victims, blood imagery or a documentary claim.', 'status': 'pending'}, {'poem_id': 583, 'rationale': 'The two-part poem gives absence several meanings through friendship and long separation. A text-led opening honours its unfilled spaces instead of imposing one empty-object metaphor.', 'status': 'pending'}, {'poem_id': 590, 'rationale': 'The remembered route moves through steps, a hidden letter, the guava tree and a garden. Let that intimate map unfold in language without turning it into an over-literal collage.', 'status': 'pending'}]
